using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough.\n3. Spread crushed tomatoes.\n4. Add torn mozzarella.\n5. Bake 10-12 minutes.\n6. Top with fresh basil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti al dente.\n2. Fry guanciale until crispy.\n3. Mix eggs and cheese.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Season with pepper.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or broil chicken.\n3. Sauté onion, garlic, ginger.\n4. Add tomato sauce and spices.\n5. Simmer, add cream.\n6. Add chicken pieces and serve with rice.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Eggs", Steps = "1. Soak rice noodles.\n2. Press and cube tofu, fry until golden.\n3. Scramble eggs.\n4. Stir-fry noodles with tamarind and fish sauce.\n5. Add tofu, sprouts, eggs.\n6. Garnish with peanuts and lime.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Cumin, Chili powder", Steps = "1. Brown beef with cumin and chili powder.\n2. Warm taco shells.\n3. Dice tomato and shred lettuce.\n4. Assemble tacos with beef.\n5. Top with cheese, lettuce, tomato, sour cream.", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, cilantro.\n4. Add lime juice and salt.\n5. Serve immediately with chips.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Tom Yum Soup", Category = "Thai", Ingredients = "Shrimp, Lemongrass, Galangal, Kaffir lime leaves, Mushrooms, Chili, Fish sauce, Lime juice", Steps = "1. Bring broth to boil with lemongrass, galangal, lime leaves.\n2. Add mushrooms.\n3. Add shrimp and chili.\n4. Season with fish sauce and lime juice.\n5. Serve hot.", AverageRating = 4.4, RatingCount = 6 },
        new Recipe { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken, Butter, Tomato puree, Cream, Garam masala, Fenugreek leaves, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices.\n2. Cook chicken in tandoor or oven.\n3. Make sauce with butter, tomato, cream, spices.\n4. Add chicken to sauce.\n5. Finish with fenugreek leaves.\n6. Serve with naan.", AverageRating = 4.9, RatingCount = 25 },
    };

    private int _nextId = 9;

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

