arguments.file_text:
@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in Categories)
    {
        <div class="col-md-3 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@category</h5>
                    <a href="/recipes/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-4">
    <a href="/submit" class="btn btn-success btn-lg">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = new();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/recipes/{Category}"

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@if (Recipes.Any())
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">
                            @GetStarDisplay(recipe.AverageRating) (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeShare.Models.Recipe> Recipes { get; set; } = new();

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(Category);
    }

    private string GetStarDisplay(double rating)
    {
        int fullStars = (int)rating;
        return new string('★', fullStars) + new string('☆', 5 - fullStars);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (Recipe is not null)
        {
            <li class="breadcrumb-item"><a href="/recipes/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        }
    </ol>
</nav>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: @Recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[2..].TrimStart();
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[3..].TrimStart();
            <li>@text</li>
        }
    </ol>

    <hr />
    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              role="button"
              aria-label="@star stars">
            ★
        </span>
    }
    <span class="ms-2 text-muted">
        @if (Submitted)
        {
            <text>Thanks for rating!</text>
        }
        else if (Recipe is not null)
        {
            <text>@Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }
    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        CurrentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetById(RecipeId);
        Submitted = true;
    }
}

.star-rating .star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s;
}

.star-rating .star.filled {
    color: #ffc107;
}

.star-rating .star:hover {
    color: #ffdb4d;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the community.
        <a href="/recipe/@SubmittedId">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" />
            <ValidationMessage For="() => NewRecipe.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="American">American</option>
                <option value="Japanese">Japanese</option>
                <option value="French">French</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => NewRecipe.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="NewRecipe.Ingredients" />
            <ValidationMessage For="() => NewRecipe.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" />
            <ValidationMessage For="() => NewRecipe.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private Recipe NewRecipe { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(NewRecipe);
        SubmittedId = NewRecipe.Id;
        SubmitSuccess = true;
    }
}

@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in Categories)
    {
        <div class="col-md-3 mb-3">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@category</h5>
                    <a href="/recipes/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-4">
    <a href="/submit" class="btn btn-success btn-lg">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = new();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/recipes/{Category}"

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@if (Recipes.Any())
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">
                            @GetStarDisplay(recipe.AverageRating) (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeShare.Models.Recipe> Recipes { get; set; } = new();

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(Category);
    }

    private string GetStarDisplay(double rating)
    {
        int fullStars = (int)rating;
        return new string('★', fullStars) + new string('☆', 5 - fullStars);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (Recipe is not null)
        {
            <li class="breadcrumb-item"><a href="/recipes/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        }
    </ol>
</nav>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="text-muted">Category: @Recipe.Category</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[2..].TrimStart();
            else if (text.Length > 3 && text[2] == '.' && char.IsDigit(text[0]) && char.IsDigit(text[1]))
                text = text[3..].TrimStart();
            <li>@text</li>
        }
    </ol>

    <hr />
    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              role="button"
              aria-label="@star stars">
            ★
        </span>
    }
    <span class="ms-2 text-muted">
        @if (Submitted)
        {
            <text>Thanks for rating!</text>
        }
        else if (Recipe is not null)
        {
            <text>@Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }
    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        CurrentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetById(RecipeId);
        Submitted = true;
    }
}

.star-rating .star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s;
}

.star-rating .star.filled {
    color: #ffc107;
}

.star-rating .star:hover {
    color: #ffdb4d;
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the community.
        <a href="/recipe/@SubmittedId">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" />
            <ValidationMessage For="() => NewRecipe.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="American">American</option>
                <option value="Japanese">Japanese</option>
                <option value="French">French</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => NewRecipe.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="NewRecipe.Ingredients" />
            <ValidationMessage For="() => NewRecipe.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps" />
            <ValidationMessage For="() => NewRecipe.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private Recipe NewRecipe { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(NewRecipe);
        SubmittedId = NewRecipe.Id;
        SubmitSuccess = true;
    }
}

