toolArgs.file_text:
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              role="button"
              aria-label="@star stars">
            ★
        </span>
    }
    <span class="ms-2 text-muted">
        @if (Submitted)
        {
            <text>Thanks for rating!</text>
        }
        else if (Recipe is not null)
        {
            <text>@Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Models.Recipe? Recipe { get; set; }
    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (Submitted) return;
        CurrentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetById(RecipeId);
        Submitted = true;
    }
}

